create extension if not exists pgcrypto;
create extension if not exists vector with schema extensions;
create type public.requirement_status as enum ('satisfied','partial','missing','needs_review','not_applicable');
create type public.processing_status as enum ('processing','ready','error');

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',created_at timestamptz not null default now());
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table public.organization_members(organization_id uuid references public.organizations(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role text not null check(role in('owner','admin','member','reviewer')),primary key(organization_id,user_id));
create table public.projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,agency text not null default '',notice_number text not null default '',deadline date,status text not null default 'preparing',created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.documents(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,name text not null,document_type text not null default 'other',storage_path text not null unique,page_count int not null default 0,status public.processing_status not null default 'processing',error_message text,uploaded_by uuid not null references public.profiles(id),uploaded_at timestamptz not null default now());
create table public.document_pages(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,page_number int not null check(page_number>0),extracted_text text not null default '',unique(document_id,page_number));
create table public.document_sections(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,title text not null default '',start_page int not null,end_page int not null,extracted_text text not null default '',sort_order int not null default 0);
create table public.requirements(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,requirement_code text not null,category text not null,requirement_text text not null,mandatory boolean not null default false,source_document_id uuid not null references public.documents(id),source_page int not null,source_section text,source_quote text,evaluation_information text,created_at timestamptz not null default now(),unique(project_id,requirement_code));
create table public.proposals(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,filename text not null,storage_path text not null unique,page_count int not null default 0,status public.processing_status not null default 'processing',uploaded_by uuid not null references public.profiles(id),uploaded_at timestamptz not null default now(),last_analyzed_at timestamptz);
create table public.proposal_sections(id uuid primary key default gen_random_uuid(),proposal_id uuid not null references public.proposals(id) on delete cascade,title text not null default '',start_page int not null,end_page int not null,extracted_text text not null default '',embedding extensions.vector(1536),sort_order int not null default 0);
create table public.requirement_mappings(id uuid primary key default gen_random_uuid(),requirement_id uuid not null unique references public.requirements(id) on delete cascade,proposal_section_id uuid references public.proposal_sections(id) on delete set null,status public.requirement_status not null default 'needs_review',confidence real check(confidence between 0 and 1),reason text not null,matched_text text,reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create table public.review_issues(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,requirement_id uuid references public.requirements(id) on delete cascade,severity text not null check(severity in('critical','major','minor')),issue_type text not null,title text not null,description text not null,status text not null default 'open',created_at timestamptz not null default now());

create index projects_org_idx on public.projects(organization_id);create index documents_project_idx on public.documents(project_id);create index requirements_project_idx on public.requirements(project_id);create index proposals_project_idx on public.proposals(project_id);create index issues_project_idx on public.review_issues(project_id,status);
alter table public.profiles enable row level security;alter table public.organizations enable row level security;alter table public.organization_members enable row level security;alter table public.projects enable row level security;alter table public.documents enable row level security;alter table public.document_pages enable row level security;alter table public.document_sections enable row level security;alter table public.requirements enable row level security;alter table public.proposals enable row level security;alter table public.proposal_sections enable row level security;alter table public.requirement_mappings enable row level security;alter table public.review_issues enable row level security;
create policy profiles_own on public.profiles for all to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy memberships_own on public.organization_members for select to authenticated using(user_id=(select auth.uid()));
create policy organizations_member on public.organizations for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=id and m.user_id=(select auth.uid())));
create policy projects_member on public.projects for all to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=organization_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.organization_members m where m.organization_id=organization_id and m.user_id=(select auth.uid())));
create policy documents_member on public.documents for all to authenticated using(exists(select 1 from public.projects p join public.organization_members m on m.organization_id=p.organization_id where p.id=project_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.projects p join public.organization_members m on m.organization_id=p.organization_id where p.id=project_id and m.user_id=(select auth.uid())));
create policy requirements_member on public.requirements for all to authenticated using(exists(select 1 from public.projects p join public.organization_members m on m.organization_id=p.organization_id where p.id=project_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.projects p join public.organization_members m on m.organization_id=p.organization_id where p.id=project_id and m.user_id=(select auth.uid())));
create policy proposals_member on public.proposals for all to authenticated using(exists(select 1 from public.projects p join public.organization_members m on m.organization_id=p.organization_id where p.id=project_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.projects p join public.organization_members m on m.organization_id=p.organization_id where p.id=project_id and m.user_id=(select auth.uid())));
create policy issues_member on public.review_issues for all to authenticated using(exists(select 1 from public.projects p join public.organization_members m on m.organization_id=p.organization_id where p.id=project_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.projects p join public.organization_members m on m.organization_id=p.organization_id where p.id=project_id and m.user_id=(select auth.uid())));
create policy document_pages_member on public.document_pages for all to authenticated using(exists(select 1 from public.documents d join public.projects p on p.id=d.project_id join public.organization_members m on m.organization_id=p.organization_id where d.id=document_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.documents d join public.projects p on p.id=d.project_id join public.organization_members m on m.organization_id=p.organization_id where d.id=document_id and m.user_id=(select auth.uid())));
create policy document_sections_member on public.document_sections for all to authenticated using(exists(select 1 from public.documents d join public.projects p on p.id=d.project_id join public.organization_members m on m.organization_id=p.organization_id where d.id=document_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.documents d join public.projects p on p.id=d.project_id join public.organization_members m on m.organization_id=p.organization_id where d.id=document_id and m.user_id=(select auth.uid())));
create policy proposal_sections_member on public.proposal_sections for all to authenticated using(exists(select 1 from public.proposals pr join public.projects p on p.id=pr.project_id join public.organization_members m on m.organization_id=p.organization_id where pr.id=proposal_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.proposals pr join public.projects p on p.id=pr.project_id join public.organization_members m on m.organization_id=p.organization_id where pr.id=proposal_id and m.user_id=(select auth.uid())));
create policy requirement_mappings_member on public.requirement_mappings for all to authenticated using(exists(select 1 from public.requirements r join public.projects p on p.id=r.project_id join public.organization_members m on m.organization_id=p.organization_id where r.id=requirement_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.requirements r join public.projects p on p.id=r.project_id join public.organization_members m on m.organization_id=p.organization_id where r.id=requirement_id and m.user_id=(select auth.uid())));
grant usage on schema public to authenticated;
grant select,insert,update,delete on all tables in schema public to authenticated;
revoke all on all tables in schema public from anon;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('procurement-documents','procurement-documents',false,52428800,array['application/pdf']) on conflict(id) do nothing;
create policy tenant_storage_read on storage.objects for select to authenticated using(bucket_id='procurement-documents' and exists(select 1 from public.organization_members m where m.organization_id::text=(storage.foldername(name))[1] and m.user_id=(select auth.uid())));
create policy tenant_storage_write on storage.objects for insert to authenticated with check(bucket_id='procurement-documents' and exists(select 1 from public.organization_members m where m.organization_id::text=(storage.foldername(name))[1] and m.user_id=(select auth.uid())));
create policy tenant_storage_update on storage.objects for update to authenticated using(bucket_id='procurement-documents' and exists(select 1 from public.organization_members m where m.organization_id::text=(storage.foldername(name))[1] and m.user_id=(select auth.uid()))) with check(bucket_id='procurement-documents' and exists(select 1 from public.organization_members m where m.organization_id::text=(storage.foldername(name))[1] and m.user_id=(select auth.uid())));
create policy tenant_storage_delete on storage.objects for delete to authenticated using(bucket_id='procurement-documents' and exists(select 1 from public.organization_members m where m.organization_id::text=(storage.foldername(name))[1] and m.user_id=(select auth.uid()) and m.role in('owner','admin')));
